import{_ as e,o as s,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"플러그인","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/plugins.md","filePath":"ko-KR/user-guide/settings/plugins.md","lastUpdated":1785214938000}'),n={name:"ko-KR/user-guide/settings/plugins.md"};function o(i,t,p,g,d,l){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="플러그인" tabindex="-1">플러그인 <a class="header-anchor" href="#플러그인" aria-label="Permalink to &quot;플러그인&quot;">​</a></h1><p>설치된 모든 플러그인을 나열하며, 페이지 헤더에 현재 로드된 Plugin SDK 버전이 배지로 표시됩니다 (<a href="./../../dev-guide/">개발자 매뉴얼</a>과 플러그인을 맞춰볼 때 유용합니다).</p><h2 id="플러그인별-카드" tabindex="-1">플러그인별 카드 <a class="header-anchor" href="#플러그인별-카드" aria-label="Permalink to &quot;플러그인별 카드&quot;">​</a></h2><p>설치된 각 플러그인은 아이콘, 이름, 버전, DLL 파일명, <strong>전체 기능 설명</strong>을 보여주는 카드를 얻습니다.</p><p>카드를 클릭하면 펼쳐지면서 등록된 컴포넌트가 유형별(검색 제공자, 동적 메뉴 제공자 등)로 그룹화되어 나타납니다 — 전환 가능한 각 컴포넌트는 자체 <strong>활성화/비활성화 체크박스</strong>를 가지며, 필수로 표시된 컴포넌트는 대신 자물쇠 아이콘을 보여주고 끌 수 없습니다. 컴포넌트에 마우스를 올리면 <strong>상세 기능 툴팁</strong>이 나타납니다.</p><p>그룹(또는 플러그인 전체)에 전환 가능한 컴포넌트가 둘 이상 있으면, 헤더 옆에 <strong>모두 선택 / 모두 선택 해제</strong> 링크가 나타나 한 번에 하나씩이 아니라 그 범위의 모든 체크박스를 한꺼번에 뒤집을 수 있습니다.</p><p>플러그인이 자체 설정(단순한 활성화/비활성화를 넘어선 커스텀 설정)을 노출한다면, 카드 헤더에 <strong>구성</strong> 버튼이 나타나 해당 플러그인 자체의 설정 대화상자를 엽니다.</p><p>페이지 하단의 배너는 일부 컴포넌트 토글이 SwiftList를 재시작한 후에만 적용된다는 점을 상기시켜 줍니다.</p><p>설치된 플러그인이 없다면, 페이지는 대신 빈 상태 메시지를 보여줍니다.</p><p>플러그인 자체의 <strong>구성</strong> 대화상자가 실제로 어떤 모습인지에 대한 구체적인 예시(예: 트리거 키워드 변경)는 <a href="./../instant-answers.html">즉시 답변 및 키워드 단축 명령</a>을 참고하세요.</p>',10)])])}const c=e(n,[["render",o]]);export{_ as __pageData,c as default};
